    current_field = []
    in_quotes = False
    i = 0
    n = len(line)
    while i < n:
        char = line[i]
        if char == '"':
            if in_quotes and i + 1 < n and (line[i + 1] == '"'):
                current_field.append('"')
                i += 2
                continue
            else:
                in_quotes = not in_quotes
                i += 1
                continue
        elif char == ',':
            if in_quotes:
                current_field.append(',')
            else:
                fields.append(''.join(current_field))
                current_field = []
            i += 1
        else:
            current_field.append(char)
            i += 1
    if in_quotes:
        raise ValueError('Unterminated quoted field')
